46: // LimitRule provides connection restrictions for domains.
47: // Both DomainRegexp and DomainGlob can be used to specify
48: // the included domains patterns, but at least one is required.
49: // There can be two kind of limitations:
50: //   - Parallelism: Set limit for the number of concurrent requests to matching domains
51: //   - Delay: Wait specified amount of time between requests (parallelism is 1 in this case)
52: type LimitRule struct {
53: 	// DomainRegexp is a regular expression to match against domains
54: 	DomainRegexp string
55: 	// DomainGlob is a glob pattern to match against domains
56: 	DomainGlob string
57: 	// Delay is the duration to wait before creating a new request to the matching domains
58: 	Delay time.Duration
59: 	// RandomDelay is the extra randomized duration to wait added to Delay before creating a new request
60: 	RandomDelay time.Duration
61: 	// Parallelism is the number of the maximum allowed concurrent requests of the matching domains
62: 	Parallelism    int
63: 	waitChan       chan bool
64: 	compiledRegexp *regexp.Regexp
65: 	compiledGlob   glob.Glob
66: 	lock           sync.Mutex
67: }
68: 
69: // Init initializes the private members of LimitRule.
70: //
71: // Init is idempotent: once a LimitRule has been successfully initialized,
72: // subsequent calls are no-ops. This makes it safe to share a single
73: // *LimitRule across multiple Collectors via Collector.Limit — without this,
74: // the second Collector's Limit() call would (a) replace waitChan and
75: // orphan the first Collector's already-acquired slots, deadlocking its
76: // in-flight requests' defer <-r.waitChan, and (b) race with concurrent
77: // Match() reads of compiledRegexp / compiledGlob.
78: func (r *LimitRule) Init() error {
79: 	r.lock.Lock()
80: 	defer r.lock.Unlock()
81: 
82: 	if r.waitChan != nil {
83: 		return nil
84: 	}
85: 	hasPattern := false
86: 	if r.DomainRegexp != "" {
87: 		c, err := regexp.Compile(r.DomainRegexp)
88: 		if err != nil {
89: 			return err
90: 		}
91: 		r.compiledRegexp = c
92: 		hasPattern = true
93: 	}
94: 	if r.DomainGlob != "" {
95: 		c, err := glob.Compile(r.DomainGlob)
96: 		if err != nil {
97: 			return err
98: 		}
99: 		r.compiledGlob = c
100: 		hasPattern = true
101: 	}
102: 	if !hasPattern {
103: 		return ErrNoPattern
104: 	}
105: 	r.waitChan = make(chan bool, max(r.Parallelism, 1))
106: 	return nil
107: }
