54: func (s *InMemoryStorage) Init() error {
55: 	if s.visitedURLs == nil {
56: 		s.visitedURLs = make(map[uint64]bool)
57: 	}
58: 	if s.lock == nil {
59: 		s.lock = &sync.RWMutex{}
60: 	}
61: 	if s.jar == nil {
