636: func (c *Collector) scrape(u, method string, depth int, requestData io.Reader, ctx *Context, hdr http.Header, checkRevisit bool) error {
637: 	parsedWhatwgURL, err := urlParser.Parse(u)
638: 	if err != nil {
639: 		return err
640: 	}
641: 	parsedURL, err := url.Parse(parsedWhatwgURL.Href(false))
642: 	if err != nil {
643: 		return err
644: 	}
645: 	if hdr == nil {
646: 		hdr = http.Header{}
647: 		if c.Headers != nil {
648: 			for k, v := range *c.Headers {
649: 				for _, value := range v {
650: 					hdr.Add(k, value)
651: 				}
652: 			}
653: 		}
654: 	}
655: 	if _, ok := hdr["User-Agent"]; !ok {
656: 		hdr.Set("User-Agent", c.UserAgent)
657: 	}
658: 	if seeker, ok := requestData.(io.ReadSeeker); ok {
659: 		_, err := seeker.Seek(0, io.SeekStart)
660: 		if err != nil {
661: 			return err
662: 		}
663: 	}
664: 
665: 	req, err := http.NewRequest(method, parsedURL.String(), requestData)
666: 	if err != nil {
667: 		return err
668: 	}
669: 	req.Header = hdr
670: 	// The Go HTTP API ignores "Host" in the headers, preferring the client
671: 	// to use the Host field on Request.
672: 	if hostHeader := hdr.Get("Host"); hostHeader != "" {
673: 		req.Host = hostHeader
674: 	}
675: 	// note: once 1.13 is minimum supported Go version,
676: 	// replace this with http.NewRequestWithContext
677: 	req = req.WithContext(context.WithValue(c.Context, CheckRevisitKey, checkRevisit))
678: 
679: 	if err := c.requestCheck(parsedURL, method, req.GetBody, depth, checkRevisit); err != nil {
680: 		return err
681: 	}
682: 	u = parsedURL.String()
683: 	c.wg.Add(1)
684: 	if c.Async {
685: 		go c.fetch(u, method, depth, requestData, ctx, hdr, req)
686: 		return nil
