691: func (c *Collector) fetch(u, method string, depth int, requestData io.Reader, ctx *Context, hdr http.Header, req *http.Request) error {
692: 	defer c.wg.Done()
693: 	if ctx == nil {
694: 		ctx = NewContext()
695: 	}
696: 	request := &Request{
697: 		URL:       req.URL,
698: 		Headers:   &req.Header,
699: 		Host:      req.Host,
700: 		Ctx:       ctx,
701: 		Depth:     depth,
702: 		Method:    method,
703: 		Body:      requestData,
704: 		collector: c,
705: 		ID:        c.requestCount.Add(1),
706: 	}
707: 
708: 	if req.Header.Get("Accept") == "" {
709: 		req.Header.Set("Accept", "*/*")
710: 	}
711: 
712: 	c.handleOnRequest(request)
713: 
714: 	if request.abort {
715: 		return nil
716: 	}
717: 
718: 	if method == "POST" && req.Header.Get("Content-Type") == "" {
719: 		req.Header.Add("Content-Type", "application/x-www-form-urlencoded")
720: 	}
721: 
722: 	var hTrace *HTTPTrace
723: 	if c.TraceHTTP {
724: 		hTrace = &HTTPTrace{}
725: 		req = hTrace.WithTrace(req)
726: 	}
727: 	origURL := req.URL
728: 	checkResponseHeadersFunc := func(req *http.Request, statusCode int, headers http.Header) bool {
729: 		if req.URL != origURL {
730: 			request.URL = req.URL
731: 			request.Headers = &req.Header
732: 		}
733: 		c.handleOnResponseHeaders(&Response{Ctx: ctx, Request: request, StatusCode: statusCode, Headers: &headers})
734: 		return !request.abort
735: 	}
736: 	checkRequestHeadersFunc := func(req *http.Request) bool {
737: 		c.handleOnRequestHeaders(request)
738: 		return !request.abort
739: 	}
740: 	response, err := c.backend.Cache(req, c.MaxBodySize, checkRequestHeadersFunc, checkResponseHeadersFunc, c.CacheDir, c.CacheExpiration)
741: 	if proxyURL, ok := req.Context().Value(ProxyURLKey).(string); ok {
742: 		request.ProxyURL = proxyURL
743: 	}
744: 	if err := c.handleOnError(response, err, request, ctx); err != nil {
745: 		return err
746: 	}
747: 	c.responseCount.Add(1)
748: 	response.Ctx = ctx
749: 	response.Request = request
750: 	response.Trace = hTrace
751: 
752: 	err = response.fixCharset(c.DetectCharset, request.ResponseCharacterEncoding)
753: 	if err != nil {
754: 		return err
755: 	}
756: 
757: 	c.handleOnResponse(response)
758: 
759: 	err = c.handleOnHTML(response)
760: 	if err != nil {
761: 		c.handleOnError(response, err, request, ctx)
762: 	}
763: 
764: 	err = c.handleOnXML(response)
765: 	if err != nil {
766: 		c.handleOnError(response, err, request, ctx)
767: 	}
768: 
769: 	c.handleOnScraped(response)
770: 
771: 	return err
772: }
