774: func (c *Collector) requestCheck(parsedURL *url.URL, method string, getBody func() (io.ReadCloser, error), depth int, checkRevisit bool) error {
775: 	u := parsedURL.String()
776: 	if c.MaxDepth > 0 && c.MaxDepth < depth {
777: 		return ErrMaxDepth
778: 	}
779: 	if c.MaxRequests > 0 && c.requestCount.Load() >= c.MaxRequests {
780: 		return ErrMaxRequests
781: 	}
782: 	if err := c.checkFilters(u, parsedURL.Hostname()); err != nil {
783: 		return err
784: 	}
785: 	if method != "HEAD" && !c.IgnoreRobotsTxt {
786: 		if err := c.checkRobots(parsedURL); err != nil {
787: 			return err
788: 		}
789: 	}
790: 	if checkRevisit && !c.AllowURLRevisit {
791: 		// TODO weird behaviour, it allows CheckHead to work correctly,
792: 		// but it should probably better be solved with
793: 		// "check-but-not-save" flag or something
794: 		if method != "GET" && getBody == nil {
795: 			return nil
796: 		}
797: 
798: 		var body io.ReadCloser
799: 		if getBody != nil {
800: 			var err error
801: 			body, err = getBody()
802: 			if err != nil {
803: 				return err
804: 			}
805: 			defer body.Close()
806: 		}
807: 		uHash := requestHash(u, body)
808: 		visited, err := c.store.IsVisited(uHash)
809: 		if err != nil {
810: 			return err
811: 		}
812: 		if visited {
813: 			return &AlreadyVisitedError{parsedURL}
814: 		}
815: 		return c.store.Visited(uHash)
816: 	}
817: 	return nil
818: }
