821: 	if len(c.DisallowedURLFilters) > 0 {
822: 		if isMatchingFilter(c.DisallowedURLFilters, []byte(URL)) {
823: 			return ErrForbiddenURL
824: 		}
825: 	}
826: 	if len(c.URLFilters) > 0 {
