847: func (c *Collector) checkRobots(u *url.URL) error {
848: 	c.lock.RLock()
849: 	robot, ok := c.robotsMap[u.Host]
850: 	c.lock.RUnlock()
851: 
852: 	if !ok {
853: 		// no robots file cached
854: 
855: 		// Prepare request,
856: 		req, err := http.NewRequest("GET", u.Scheme+"://"+u.Host+"/robots.txt", nil)
857: 		if err != nil {
858: 			return err
859: 		}
860: 		hdr := http.Header{}
861: 		if c.Headers != nil {
862: 			for k, v := range *c.Headers {
863: 				for _, value := range v {
864: 					hdr.Add(k, value)
865: 				}
866: 			}
867: 		}
868: 		if _, ok := hdr["User-Agent"]; !ok {
869: 			hdr.Set("User-Agent", c.UserAgent)
870: 		}
871: 		req.Header = hdr
872: 		// The Go HTTP API ignores "Host" in the headers, preferring the client
873: 		// to use the Host field on Request.
874: 		if hostHeader := hdr.Get("Host"); hostHeader != "" {
875: 			req.Host = hostHeader
876: 		}
877: 
878: 		resp, err := c.backend.Client.Do(req)
879: 		if err != nil {
880: 			return err
881: 		}
882: 		defer resp.Body.Close()
883: 
884: 		robot, err = robotstxt.FromResponse(resp)
885: 		if err != nil {
886: 			return err
887: 		}
888: 		c.lock.Lock()
889: 		c.robotsMap[u.Host] = robot
890: 		c.lock.Unlock()
891: 	}
892: 
893: 	uaGroup := robot.FindGroup(c.UserAgent)
894: 	if uaGroup == nil {
895: 		return nil
896: 	}
897: 
898: 	eu := u.EscapedPath()
899: 	if u.RawQuery != "" {
900: 		eu += "?" + u.Query().Encode()
901: 	}
902: 	if !uaGroup.Test(eu) {
903: 		return ErrRobotsTxtBlocked
904: 	}
905: 	return nil
906: }
