121: 	i := 0
122: 	h.DOM.Find(goquerySelector).EachWithBreak(func(_ int, s *goquery.Selection) bool {
123: 		for _, n := range s.Nodes {
124: 			if callback(i, NewHTMLElementFromSelectionNode(h.Response, s, n, i)) {
125: 				i++
126: 				return true
127: 			}
128: 		}
129: 		return false
130: 	})
