1179: func (c *Collector) handleOnHTML(resp *Response) error {
1180: 	c.lock.RLock()
1181: 	htmlCallbacks := slices.Clone(c.htmlCallbacks)
1182: 	c.lock.RUnlock()
1183: 
1184: 	if len(htmlCallbacks) == 0 {
1185: 		return nil
1186: 	}
1187: 
1188: 	contentType := resp.Headers.Get("Content-Type")
1189: 	if contentType == "" {
1190: 		contentType = http.DetectContentType(resp.Body)
1191: 	}
1192: 	// implementation of mime.ParseMediaType without parsing the params
1193: 	// part
1194: 	mediatype, _, _ := strings.Cut(contentType, ";")
1195: 	mediatype = strings.TrimSpace(strings.ToLower(mediatype))
1196: 
1197: 	// TODO we also want to parse application/xml as XHTML if it has
1198: 	// appropriate doctype
1199: 	switch mediatype {
1200: 	case "text/html", "application/xhtml+xml":
1201: 	default:
1202: 		return nil
1203: 	}
1204: 
1205: 	doc, err := goquery.NewDocumentFromReader(bytes.NewBuffer(resp.Body))
1206: 	if err != nil {
1207: 		return err
1208: 	}
1209: 	if href, found := doc.Find("base[href]").Attr("href"); found {
1210: 		u, err := urlParser.ParseRef(resp.Request.URL.String(), href)
1211: 		if err == nil {
1212: 			baseURL, err := url.Parse(u.Href(false))
1213: 			if err == nil {
1214: 				resp.Request.baseURL = baseURL
1215: 			}
1216: 		}
1217: 
1218: 	}
1219: 	for _, cc := range htmlCallbacks {
1220: 		if !cc.active.Load() {
1221: 			continue
1222: 		}
1223: 		i := 0
1224: 		doc.Find(cc.Selector).Each(func(_ int, s *goquery.Selection) {
1225: 			for _, n := range s.Nodes {
1226: 				e := NewHTMLElementFromSelectionNode(resp, s, n, i)
1227: 				i++
1228: 				if c.debugger != nil {
1229: 					c.debugger.Event(createEvent("html", resp.Request.ID, c.ID, map[string]string{
1230: 						"selector": cc.Selector,
1231: 						"url":      resp.Request.URL.String(),
1232: 					}))
