1241: func (c *Collector) handleOnXML(resp *Response) error {
1242: 	c.lock.RLock()
1243: 	xmlCallbacks := slices.Clone(c.xmlCallbacks)
1244: 	c.lock.RUnlock()
1245: 
1246: 	if len(xmlCallbacks) == 0 {
1247: 		return nil
1248: 	}
1249: 	contentType := strings.ToLower(resp.Headers.Get("Content-Type"))
1250: 	// Parse the media type without parameters (e.g. charset)
1251: 	mediatype, _, _ := strings.Cut(contentType, ";")
1252: 	mediatype = strings.TrimSpace(mediatype)
1253: 	isXMLFile := strings.HasSuffix(strings.ToLower(resp.Request.URL.Path), ".xml") || strings.HasSuffix(strings.ToLower(resp.Request.URL.Path), ".xml.gz")
1254: 	// Check for actual XML media types: text/xml, application/xml, or *+xml (e.g. application/rss+xml).
1255: 	// Do NOT match types that merely contain "xml" in the name (e.g. .xlsx MIME types).
1256: 	isXMLContent := mediatype == "text/xml" || mediatype == "application/xml" || strings.HasSuffix(mediatype, "+xml")
1257: 	if !strings.Contains(contentType, "html") && !isXMLContent && !isXMLFile {
1258: 		return nil
1259: 	}
1260: 
1261: 	if strings.Contains(contentType, "html") {
1262: 		doc, err := htmlquery.Parse(bytes.NewBuffer(resp.Body))
1263: 		if err != nil {
1264: 			return err
1265: 		}
1266: 		if e := htmlquery.FindOne(doc, "//base"); e != nil {
1267: 			for _, a := range e.Attr {
1268: 				if a.Key == "href" {
1269: 					baseURL, err := resp.Request.URL.Parse(a.Val)
1270: 					if err == nil {
1271: 						resp.Request.baseURL = baseURL
1272: 					}
1273: 					break
1274: 				}
1275: 			}
1276: 		}
1277: 
1278: 		for _, cc := range xmlCallbacks {
1279: 			if !cc.active.Load() {
1280: 				continue
1281: 			}
1282: 			for i, n := range htmlquery.Find(doc, cc.Query) {
1283: 				e := NewXMLElementFromHTMLNode(resp, n)
1284: 				e.Index = i
1285: 				if c.debugger != nil {
1286: 					c.debugger.Event(createEvent("xml", resp.Request.ID, c.ID, map[string]string{
1287: 						"selector": cc.Query,
1288: 						"url":      resp.Request.URL.String(),
1289: 					}))
1290: 				}
1291: 				cc.Function(e)
1292: 			}
1293: 		}
1294: 	} else if isXMLContent || isXMLFile {
1295: 		doc, err := xmlquery.Parse(bytes.NewBuffer(resp.Body))
1296: 		if err != nil {
1297: 			return err
1298: 		}
1299: 
1300: 		for _, cc := range xmlCallbacks {
1301: 			if !cc.active.Load() {
1302: 				continue
1303: 			}
1304: 			xmlquery.FindEach(doc, cc.Query, func(i int, n *xmlquery.Node) {
1305: 				e := NewXMLElementFromXMLNode(resp, n)
1306: 				if c.debugger != nil {
1307: 					c.debugger.Event(createEvent("xml", resp.Request.ID, c.ID, map[string]string{
1308: 						"selector": cc.Query,
1309: 						"url":      resp.Request.URL.String(),
1310: 					}))
1311: 				}
1312: 				cc.Function(e)
1313: 			})
1314: 		}
1315: 	}
1316: 	return nil
1317: }
