1461: func (c *Collector) checkRedirectFunc() func(req *http.Request, via []*http.Request) error {
1462: 	return func(req *http.Request, via []*http.Request) error {
1463: 		if err := c.checkFilters(req.URL.String(), req.URL.Hostname()); err != nil {
1464: 			return fmt.Errorf("Not following redirect to %q: %w", req.URL, err)
1465: 		}
1466: 
1467: 		// Page may set cookies and respond with a redirect to itself.
1468: 		// Some example of such redirect "cycles":
1469: 		//
1470: 		// example.com -(set cookie)-> example.com
1471: 		// example.com -> auth.example.com -(set cookie)-> example.com
1472: 		// www.example.com -> example.com -(set cookie)-> example.com
1473: 		//
1474: 		// We must not return "already visited" error in such cases.
1475: 		// So ignore redirect cycles when checking for URL revisit.
1476: 		redirectCycle := false
1477: 		normalizedURL := normalizeURL(req.URL.String())
1478: 		for _, viaReq := range via {
1479: 			viaURL := normalizeURL(viaReq.URL.String())
1480: 			if viaURL == normalizedURL {
1481: 				redirectCycle = true
1482: 				break
1483: 			}
1484: 		}
1485: 
1486: 		if !c.AllowURLRevisit && !redirectCycle {
1487: 			var body io.ReadCloser
1488: 			if req.GetBody != nil {
1489: 				var err error
1490: 				body, err = req.GetBody()
1491: 				if err != nil {
1492: 					return err
1493: 				}
1494: 				defer body.Close()
1495: 			}
1496: 			uHash := requestHash(req.URL.String(), body)
1497: 			visited, err := c.store.IsVisited(uHash)
1498: 			if err != nil {
1499: 				return err
1500: 			}
1501: 			if visited {
1502: 				if checkRevisit, ok := req.Context().Value(CheckRevisitKey).(bool); !ok || checkRevisit {
1503: 					return &AlreadyVisitedError{req.URL}
1504: 				}
1505: 			}
1506: 			err = c.store.Visited(uHash)
1507: 			if err != nil {
1508: 				return err
1509: 			}
1510: 		}
1511: 
1512: 		if c.redirectHandler != nil {
1513: 			return c.redirectHandler(req, via)
1514: 		}
1515: 
1516: 		// Honor golangs default of maximum of 10 redirects
1517: 		if len(via) >= 10 {
1518: 			return http.ErrUseLastResponse
1519: 		}
1520: 
1521: 		lastRequest := via[len(via)-1]
1522: 
1523: 		// If domain has changed, remove the Authorization-header if it exists
1524: 		if req.URL.Host != lastRequest.URL.Host {
1525: 			req.Header.Del("Authorization")
1526: 		}
1527: 
1528: 		return nil
1529: 	}
1530: }
