1574: func createMultipartReader(boundary string, data map[string][]byte) io.Reader {
1575: 	dashBoundary := "--" + boundary
1576: 
1577: 	body := []byte{}
1578: 	buffer := bytes.NewBuffer(body)
1579: 
1580: 	buffer.WriteString("Content-type: multipart/form-data; boundary=" + boundary + "\n\n")
1581: 	for contentType, content := range data {
1582: 		buffer.WriteString(dashBoundary + "\n")
1583: 		buffer.WriteString("Content-Disposition: form-data; name=" + contentType + "\n")
1584: 		buffer.WriteString(fmt.Sprintf("Content-Length: %d \n\n", len(content)))
1585: 		buffer.Write(content)
1586: 		buffer.WriteString("\n")
1587: 	}
1588: 	buffer.WriteString(dashBoundary + "--\n\n")
1589: 	return bytes.NewReader(buffer.Bytes())
1590: 
1591: }
